#!/usr/bin/env node
/**
 * Fail the build when the bundled sound folder drifts from its manifest.
 *
 * ZAICODE can play three separate audio layers:
 *
 *   1. `packages/ui/src/assets/fastprompter-sounds/` -- the bundled fallback.
 *      Every file here is generated by `scripts/audio/generate_fallback_sounds.py`
 *      or is an original operator asset named in `scripts/audio/fallback-sounds.manifest`.
 *   2. the operator's `customization\sounds\` folder -- read live through the
 *      desktop bridge, never packaged.
 *   3. an imported custom notification sound -- stored in IndexedDB, never packaged.
 *
 * Only layer 1 rides in an installer, so only layer 1 needs an allowlist.  A
 * WAV in that folder which the manifest does not name is either a forgotten
 * deletion or a reintroduction of third-party audio; both must stop the build.
 * Audio anywhere ELSE in the repository is the same failure -- this repository
 * shipped 1311 game and GoldSrc files that way once.
 *
 * Usage:
 *   node scripts/audio/verify-fallback-sounds.mjs [--root .]
 */
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative, resolve } from "node:path";

const SOUNDS_REL = join("packages", "ui", "src", "assets", "fastprompter-sounds");
const MANIFEST_REL = join("scripts", "audio", "fallback-sounds.manifest");
const AUDIO = /\.(wav|mp3|ogg|flac)$/i;
const SKIP = new Set(["node_modules", ".git", "dist", "build", "out", ".turbo"]);

/**
 * Sanctioned audio outside the fallback folder, each with its provenance
 * written down here rather than left implicit.  Add a row only after the
 * rights question is answered; "it was already there" is not an answer.
 */
const ALLOWED_ELSEWHERE = new Map([
  [
    "packages/ui/src/assets/notification-sounds/task-notification-pop.mp3",
    "upstream ZAICODE notification cue, present since the initial open-source commit",
  ],
]);

function walk(dir, root, out) {
  for (const name of readdirSync(dir)) {
    if (SKIP.has(name)) continue;
    const full = join(dir, name);
    if (statSync(full).isDirectory()) walk(full, root, out);
    else out.push(relative(root, full).replaceAll("\\", "/"));
  }
}

export function verifyFallbackSounds(root = ".") {
  const base = resolve(root);
  const manifestPath = join(base, MANIFEST_REL);
  let text;
  try {
    text = readFileSync(manifestPath, "utf8");
  } catch {
    throw new Error(`sound allowlist missing: ${manifestPath}`);
  }
  const allowed = new Set(
    text
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter((line) => line && !line.startsWith("#"))
      .map((line) => line.replaceAll("\\", "/").toLowerCase()),
  );

  const shippedDir = join(base, SOUNDS_REL);
  let shippedFiles;
  try {
    shippedFiles = [];
    walk(shippedDir, shippedDir, shippedFiles);
  } catch {
    throw new Error(`bundled sound folder missing: ${shippedDir}`);
  }
  const shipped = new Set(
    shippedFiles.filter((rel) => AUDIO.test(rel)).map((rel) => rel.toLowerCase()),
  );

  const extra = [...shipped].filter((name) => !allowed.has(name)).sort();
  const missing = [...allowed].filter((name) => !shipped.has(name)).sort();

  const all = [];
  walk(base, base, all);
  const stray = all
    .filter((rel) => AUDIO.test(rel))
    .filter((rel) => !rel.toLowerCase().startsWith(`${SOUNDS_REL.replaceAll("\\", "/")}/`.toLowerCase()))
    .filter((rel) => !ALLOWED_ELSEWHERE.has(rel))
    .sort();

  if (extra.length || missing.length || stray.length) {
    const lines = ["bundled sound folder does not match the allowlist"];
    for (const name of extra) lines.push(`  UNLISTED (remove it or add it to the manifest): ${name}`);
    for (const name of missing) lines.push(`  MANIFESTED BUT ABSENT: ${name}`);
    for (const name of stray) lines.push(`  AUDIO OUTSIDE THE SOUND FOLDER: ${name}`);
    lines.push(`manifest: ${manifestPath}`);
    throw new Error(lines.join("\n"));
  }
  return allowed.size;
}

const invokedDirectly = process.argv[1] && resolve(process.argv[1]) === resolve(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1"));
if (invokedDirectly) {
  const argIndex = process.argv.indexOf("--root");
  const root = argIndex >= 0 ? process.argv[argIndex + 1] : ".";
  try {
    const count = verifyFallbackSounds(root);
    console.log(`sound allowlist OK (${count} files)`);
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exit(1);
  }
}
